// L'algorithme variable est isolé derrière une interface
interface ShippingCost {
    Money compute(Order order);
}

class StandardShipping implements ShippingCost { public Money compute(Order o) { /* ... */ return Money.of(5); } }
class ExpressShipping implements ShippingCost { public Money compute(Order o) { /* ... */ return Money.of(15); } }

// Le code client ignore la variante : on branche la stratégie
class Checkout {
    private final ShippingCost shipping; // injectée
    Checkout(ShippingCost shipping) { this.shipping = shipping; }
    Money total(Order o) { return o.subtotal().plus(shipping.compute(o)); }
}

interface Node { <R> R accept(Visitor<R> v); }
record Num(double v) implements Node { public <R> R accept(Visitor<R> vi){ return vi.visit(this); } }
record Add(Node l, Node r) implements Node { public <R> R accept(Visitor<R> vi){ return vi.visit(this); } }

interface Visitor<R> { R visit(Num n); R visit(Add a); }

// Nouvelle opération = nouveau visiteur, sans toucher aux Node :
class Eval implements Visitor<Double> {
    public Double visit(Num n) { return n.v(); }
    public Double visit(Add a) { return a.l().accept(this) + a.r().accept(this); }
}
class Print implements Visitor<String> {
    public String visit(Num n) { return String.valueOf(n.v()); }
    public String visit(Add a) { return "(" + a.l().accept(this) + " + " + a.r().accept(this) + ")"; }
}
